-- Memoria: ukážkové (DEMO) dáta na prezentáciu. Všetko is_demo = true, zmaže sa: select public.memoria_purge_demo();
-- Autor záznamov: Erik Kril (nastavené cez request.jwt.claims, aby aktivita mala meno).
select set_config('request.jwt.claims', '{"sub":"3513534d-3cc0-4e80-a436-e64891489bcb","role":"authenticated"}', false);







-- Faktúry: mesačné zmluvné faktúry generované, jednorazové vypísané.
  net_amount, vat_amount, total_amount, currency, description, category, funding_source, period_year, period_month, import_source, is_demo)
select s.supplier_id::uuid, s.contract_id::uuid, s.prefix || to_char(d, 'YYYY-MM'),
  case when d >= date '2026-09-01' then date '2026-09-18' else (d + interval '27 day')::date end,
  case when d >= date '2026-09-01' then date '2026-10-18' else (d + interval '57 day')::date end,
  case when d >= date '2026-09-01' then null else (d + interval '47 day')::date end,
  case when d >= date '2026-09-01' then 'pending' else 'paid' end,
  n.net, round(n.net * 0.21, 2), round(n.net * 1.21, 2), 'EUR', s.descr, s.category, 'ordinary_budget',
  extract(year from d)::smallint, extract(month from d)::smallint, 'demo', true
from (values
  ('50000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'JS-', 'Gardening maintenance', 'gardening', date '2024-01-01', date '2025-10-01', 4200.0, 4200.0),
  ('50000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'VC-', 'Gardening maintenance', 'gardening', date '2025-11-01', date '2026-09-01', 4350.0, 4350.0),
  ('50000000-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000003', 'PM-', 'Pool maintenance', 'pools', date '2025-01-01', date '2026-09-01', 3100.0, 3250.0),
  ('50000000-0000-4000-8000-000000000008', 'c0000000-0000-4000-8000-000000000006', 'LB-', 'Cleaning common areas', 'staff_cleaning', date '2025-01-01', date '2026-09-01', 2800.0, 2800.0),
  ('50000000-0000-4000-8000-000000000007', 'c0000000-0000-4000-8000-000000000005', 'VIS-', 'Night security patrol', 'security', date '2025-01-01', date '2026-09-01', 6200.0, 6200.0)
) as s(supplier_id, contract_id, prefix, descr, category, from_d, to_d, net_2025, net_2026)
cross join lateral generate_series(s.from_d, s.to_d, interval '1 month') as g(d0)
cross join lateral (select g.d0::date as d) dd
cross join lateral (select case when extract(year from dd.d) >= 2026 then s.net_2026 else s.net_2025 end as net) n;









