insert into public.memoria_decisions (id, title, decided_on, body, authority_basis, context, alternatives, decision, rationale, votes_for, votes_against, votes_abstain, status, outcome_review, outcome_reviewed_on, status_note, is_demo) values
('d0000000-0000-4000-8000-000000000001', 'Gardening maintenance 2024–2025: award contract', '2024-01-18', 'board', 'Estatutos art. XXII.4; budget 2024 approved by AGM', 'Previous gardening contract expired. Owners asked for better irrigation care.', '3 quotes: Jardines del Sol 4,200 €/month, Green Andalucía 4,750 €/month, renew with previous supplier at 4,600 €/month.', 'Award to Jardines del Sol S.L. for 22 months (1/1/2024–31/10/2025).', 'Lowest price, references from two nearby communities, includes irrigation repairs up to 300 €/month.', 4, 0, 1, 'active', 'Did not work out: quality dropped in 2025, 4 missed visits, many owner complaints. Lesson: include measurable service levels and penalties in the contract.', '2025-09-30', null, true),
('d0000000-0000-4000-8000-000000000002', 'Gardening maintenance from November 2025: new supplier', '2025-09-24', 'board', 'Estatutos art. XXII.4', 'Contract with Jardines del Sol ends 31/10/2025. Service level was poor (see review of the 2024 decision).', 'Renew Jardines del Sol (4,600 €/month); Verde Costa (4,350 €/month); Green Andalucía (4,900 €/month).', 'Award to Verde Costa Paisajismo S.L. from 1/11/2025, 14 months, auto-renewal, 60 days notice. Weekly written report and service levels with penalties included.', 'Best price and the only offer with measurable service levels. Visited two of their gardens in Estepona.', 5, 0, 0, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000003', 'Do not renew Jardines del Sol', '2025-07-10', 'board', 'Estatutos art. XXII.4', 'Four missed visits and repeated owner complaints in the first half of 2025.', null, 'Give notice on time and start a new tender for gardening from November 2025.', 'Service quality below contract; 3 written warnings without improvement.', 5, 0, 0, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000004', 'Urgent repair of pool 3 pump: ratification', '2026-07-15', 'board', 'Estatutos art. XXX (30) (ratification of urgent unbudgeted expense)', 'Pool 3 pump failed on Saturday 4/7/2026 during peak season. President and administrator approved an urgent repair (joint signature).', null, 'Pending ratification at the next board meeting.', null, null, null, null, 'active', null, null, 'Invoice recorded; ratification still to be voted.', true),
('d0000000-0000-4000-8000-000000000005', 'Garage cameras blocks 1–23: collect 3 quotes', '2026-07-15', 'board', 'AGM 23/04/2026 (cameras up to 9,000 € from reserve fund)', 'The AGM approved connecting garage cameras to the central system, maximum 9,000 € from the reserve fund.', null, 'Collect at least 3 comparable quotes using the same written specification. Decision at the October board meeting.', 'Resolution on conflicts of interest (AGM 2026, 6g) and comparable offers.', 4, 0, 0, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000006', 'Pool maintenance: prepare tender for 2027', '2026-07-15', 'board', 'Estatutos art. XXII.4', 'The pool contract dates from 2021 and was never compared with other offers.', null, 'Ask the administrator for the current contract and prepare a tender before renewal.', null, 4, 0, 1, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000007', 'Community insurance: compare before renewal', '2026-07-15', 'president', 'Estatutos art. XXXIV (president decides insurance cover)', 'Premium increased 18% in 2 years; 3 water-damage claims in 2025.', null, 'Broker to present 2 alternative offers with the same cover before 15/10/2026.', null, null, null, null, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000008', 'Accessibility ramp at pool 2 entrance', '2026-05-20', 'board', 'Estatutos art. XXII.4; LPH art. 10 (accessibility works)', 'Request from owners with reduced mobility.', null, 'Request building licence and 2 quotes.', null, 5, 0, 0, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000009', 'Garage gates: service contract review', '2026-03-12', 'administrator', 'Estatutos art. XXVII (ordinary maintenance)', 'Two breakdowns of gate 3 in winter.', null, 'Keep current service provider; semi-annual inspection recorded in Memoria calendar.', null, null, null, null, 'active', null, null, null, true),
('d0000000-0000-4000-8000-000000000010', 'LED replacement of garden lights (phase 1)', '2026-02-10', 'board', 'Estatutos art. XXII.4; budget 2026', 'Old halogen garden lights, high consumption.', 'Full replacement now (24,000 €) vs. phased by zones.', 'Phase 1: zones A and B, maximum 8,500 €.', 'Payback about 3 years; phased approach keeps the reserve fund above 10%.', 3, 1, 1, 'active', null, null, null, true);
